  3122  static bool ignore_elf_section(Elf64_Shdr *hdr, const char *name)
  3123  {
  3124          /* no special handling of .strtab */
  3125          if (hdr->sh_type == SHT_STRTAB)
  3126                  return true;
  3127
  3128          /* ignore .llvm_addrsig section as well */
  3129          if (hdr->sh_type == SHT_LLVM_ADDRSIG)
  3130                  return true;
  3131
  3132          /* no subprograms will lead to an empty .text section, ignore it */
  3133          if (hdr->sh_type == SHT_PROGBITS && hdr->sh_size == 0 &&
  3134              strcmp(name, ".text") == 0)
  3135                  return true;
  3136
  3137          /* DWARF sections */
  3138          if (is_sec_name_dwarf(name))
  3139                  return true;
  3140
  3141          if (str_has_pfx(name, ".rel")) {
  3142                  name += sizeof(".rel") - 1;
  3143                  /* DWARF section relocations */
  3144                  if (is_sec_name_dwarf(name))
  3145                          return true;
  3146
  3147                  /* .BTF and .BTF.ext don't need relocations */
  3148                  if (strcmp(name, BTF_ELF_SEC) == 0 ||
  3149                      strcmp(name, BTF_EXT_ELF_SEC) == 0)
  3150                          return true;
  3151          }
  3152
  3153          return false;
  3154  }
